INSERT INTO `ps_banners_lang` VALUES (1,1,1,'<p style=\"margin-top:10px;text-align:left;\"><span style=\"font-size:19px;color:#9b9b9b;\"></span><span style=\"color:#9b9b9b;\"><span style=\"font-size:17px;\">Limited time offer</span></span><span style=\"font-size:17px;color:#9b9b9b;\"></span></p>\n              <p style=\"margin-top:15px;text-align:left;\"><span style=\"color:#ffffff;\"><span style=\"font-size:40px;\">SUMMER <em>Sale</em></span></span></p>\n              <p style=\"margin-top:10px;text-align:left;\"><span style=\"color:#d09f67;\"><span><span style=\"font-size:20px;\">SAVE UP TO 50%</span></span></span></p>\n              <p style=\"margin-top:25px;text-align:left;\"><span style=\"color:#ffffff;\"><span style=\"font-size:16px;\">The new Versace Vanitas handbags collection is really amazing, and according to Donatella Versace it reflects the true heritage of the brand. Its a blend of the most iconoclassic elements such as the Medusa or the Barocco. A luxury accessories line designed for today woomen. And I just love it!</span></span></p>\n              <p style=\"margin-top:10px;text-align:left;\"><a class=\"btn btn-primary-gomakoil\" href=\"#\">Shop now</a></p>','<h1 style=\"text-align:center;\"></h1><h1 style=\"text-align:center;margin-top:140px;\"><span style=\"font-weight:bolder;color:#ffffff;font-family:\'Noto Sans\', sans-serif;font-size:32px;text-align:center;text-transform:uppercase;\">SPECIAL OFFER</span></h1>');
INSERT INTO `ps_banners_lang` VALUES (2,1,1,'<h1 style=\"text-align:center;\"></h1><h1 style=\"text-align:center;margin-top:140px;\"><span style=\"font-weight:bolder;color:#ffffff;font-family:\'Noto Sans\', sans-serif;font-size:32px;text-align:center;text-transform:uppercase;\">OUR STORE</span></h1>','<p style=\"margin-top:53px;\"><span style=\"color:#ffffff;font-size:16px;\">The new Versace Vanitas handbags collection is really amazing, and according to Donatella Versace it reflects the true heritage of the brand. It\'s a blend of the most iconoclassic elements such as the Medusa or the Barocco. A luxury accessories line designed for today women. And I just love it! The new Versace Vanitas handbags collection is really amazing, and according to Donatella Versace it reflects the true heritage of the brand. It\'s a blend of the most iconoclassic elements such as the Medusa or the Barocco. A luxury accessories line designed for today women. And I just love it! The new Versace Vanitas handbags collection is really amazing, and according to Donatella Versace it reflects the true heritage of the brand. It\'s a blend of the most iconoclassic elements such as the Medusa or the Barocco. A luxury accessories line designed for today women. And I just love it!</span></p><p></p>');
