INSERT INTO `ps_info_lang` VALUES (1,1,1,'<h2 style=\"text-align:center;\">Sklep Numizmatyczny.Com </h2>\n<p style=\"text-align:center;\">Monety, Banknoty, Akcesoria - profesjonalny sklep dla kolekcjonera, inwestora, dla Ciebie. </p>\n<p style=\"text-align:center;\">Kompleksowo zaopatrujemy naszych klientów w <a class=\"homePageLink\" href=\"https://localhost/1324-monety-zlote\">Monety złote</a>, <a class=\"homePageLink\" href=\"https://localhost/1338-srebrne-monety-inwestycyjne\">srebrne</a>, <a class=\"homePageLink\" href=\"https://localhost/1344-banknoty\">banknoty kolekcjonerskie</a> oraz inne wartościowe walory. Lata doświadczeń, indywidualne podejście, porady inwestycyjne, profesjonalne podejście to nasze mocne strony.</p>');
