INSERT INTO `ps_product_lang` VALUES (200,1,1,'<p style=\"text-align:left;\">Album na 200 banknotów 0 Euro.</p>\n<p style=\"text-align:left;\">Album wyróżnia twarda, kolorowa i laminowana okładka z różnymi motywami międzynarodowych banknotów.</p>\n<p style=\"text-align:left;\">Album zawiera 50 stron. Jedna strona pomieści 4 banknoty.</p>\n<p style=\"text-align:left;\">Dodatkowo obok banknotów jest miejsce na indywidualny opis każdego banknotu.</p>\n<p style=\"text-align:left;\"><strong>Dodatkowo każdy album zawiera pamiątkowy banknot Euro z limitowanej edycji „Euro Souvenir”.</strong></p>\n<p> </p>\n<p> </p>','','album-na-200-banknotow-0-euro','','','','Album na 200 Banknotów 0 Euro','','','','');
