INSERT INTO `ps_product_lang` VALUES (203,1,1,'<p style=\"text-align:justify;\">Kieszonkowy album na 40 banknotów 0 Euro.</p>\n<p style=\"text-align:left;\">Zawiera 20 kart. Zmieści 40 banknotów przy założeniu ekspozycji z jednej strony. W przypadku ekspozycji z obu stron zmieści 20 banknotów.</p>\n<p style=\"text-align:left;\">Karty są wykonane z plastiku, nie zawierają zmiękczaczy chemicznych i zapewniają bezpieczne przechowywanie i ochronę przed banknotów przed uszkodzeniem.</p>\n<p style=\"text-align:left;\">Wymiary: 150 x 95 x 20 mm</p>\n<p> </p>\n<p> </p>','','kieszonkowy-album-na-40-banknotow-0-euro','','','','Kieszonkowy Album na 40 Banknotów 0 Euro','','','','');
