INSERT INTO `ps_product_lang` VALUES (260,1,1,'<p><strong>Moneta okolicznościowa 2 złote </strong>80. Rocznica Odzyskania Niepodległości<strong><br /></strong></p>\n<p>Jest to dwudziesta moneta okolicznościowa o nominale 2 zł, która ukazała się w okresie po denominacji (1995 r.)</p>\n<p>Jest to <a href=\"/monety-100-lecie-niepodleglosci\" title=\"pierwsza z monet 2 zł nawiązujących do tematyki niepodległościowej\">pierwsza z monet 2 złotowych nawiązujących do tematyki niepodległościowej</a>.</p>\n<p style=\"text-align:justify;\">Moneta została wyemitowana, aby upamiętnić 80. rocznicę Odzyskania przez Polskę Niepodległości. Na rewersie w centralnej części monety widnieje napis: 1918 wkomponowany w stylizowane promienie, które również pojawiają się na odwrocie monety. </p>\n<p><a href=\"/monety-2-zl-okolicznosciowe-1998-rok\" title=\"Zobacz również wszystkie wyemitowane w 1998 roku monety o nominale 2 zł.\">Zobacz również wszystkie wyemitowane w 1998 roku monety o nominale 2 zł.</a><br /><a href=\"/monety-nbp-1998\" title=\"Zobacz wszystkie monety wyemitowane w 1998 roku.\">Zobacz wszystkie monety wyemitowane w 1998 roku.</a></p>','','moneta-2-zl-80-rocznica-odzyskania-niepodleglosci-1998-rok','','','','Moneta 2 zł 80. Rocznica Odzyskania Niepodległości - 1998 rok','','','','');
