INSERT INTO `ps_product_lang` VALUES (346,1,1,'<p><strong>Moneta okolicznościowa 2 złote </strong>100. rocznica utworzenia Akademii Sztuk Pięknych</p>\n<p style=\"text-align:justify;\">Jest to osiemdziesiąta piąta moneta okolicznościowa o nominale 2 zł, która ukazała się w okresie po denominacji (1995 r.) <br /><br />Moneta została wyemitowana, aby upamiętnić 100 rocznicę utworzenia Akademii Sztuk Pięknych. Na rewersie monety widnieje wizerunek obrazu panoramy przedstawiającej dziedziniec Akademii Sztuk Pięknych w Warszawie. Z prawej strony monety jest dłoń na tle ozdobnego reliefu, natomiast poniżej widniej druga dłoń trzymająca paletę oraz dwa pędzle. </p>\n<p><a href=\"/monety-2-zl-okolicznosciowe-2004-rok\" title=\"Zobacz również wszystkie wyemitowane w 2004 roku monety o nominale 2 zł.\">Zobacz również wszystkie wyemitowane w 2004 roku monety o nominale 2 zł.</a><br /><a href=\"/monety-nbp-2004\" title=\"Zobacz wszystkie monety wyemitowane w 2004 roku.\">Zobacz wszystkie monety wyemitowane w 2004 roku.</a></p>','','moneta-2-zl-akademia-sztuk-pieknych-2004-rok','','','','Moneta 2 zł Akademia Sztuk Pięknych - 2004 rok','','','','');
INSERT INTO `ps_product_lang` VALUES (347,1,1,'<p><strong>Moneta okolicznościowa 2 złote </strong>Generał brygady Stanisław F. Sosabowski (1892-1967)</p>\n<p style=\"text-align:justify;\">Jest to osiemdziesiąta czwarta moneta okolicznościowa o nominale 2 zł, która ukazała się w okresie po denominacji (1995 r.) <br /><br />Moneta została wyemitowana, aby upamiętnić Generała brygady Stanisława F. Sosabowskiego. Na rewersie monety widnieje popiersie przedstawiające generała, natomiast z jego prawej znajduje się wizerunek Bojowego Znaku Spadochronowego. Na monecie również widnieje data urodzenia oraz śmierci. </p>\n<p><a href=\"/monety-2-zl-okolicznosciowe-2004-rok\" title=\"Zobacz również wszystkie wyemitowane w 2004 roku monety o nominale 2 zł.\">Zobacz również wszystkie wyemitowane w 2004 roku monety o nominale 2 zł.</a><br /><a href=\"/monety-nbp-2004\" title=\"Zobacz wszystkie monety wyemitowane w 2004 roku.\">Zobacz wszystkie monety wyemitowane w 2004 roku.</a></p>','','moneta-2-zl-stanislaw-f-sosabowski-2004-rok','','','','Moneta 2 zł Stanisław F. Sosabowski - 2004 rok','','','','');
